#!/usr/bin/env node
// Verification driver generated by Whetstone (`wh init --action wire`).
//
// This file belongs to the repository. Whetstone scaffolds it once and never
// overwrites it unless asked (`--regenerate-driver`). Edit it freely: add
// commands, better selectors, seed data, test auth. Keep it small, keep
// every command composable, and keep output machine-readable.
//
// Node 22 or later, no dependencies. Configuration lives in driver.json
// beside this file. Evidence goes to $WH_EVIDENCE_DIR (set by `wh check`) or
// a temporary directory printed in the output; cleanup never deletes it.
//
//   node whetstone/verify/drive.mjs help
//   node whetstone/verify/drive.mjs doctor --json
//   node whetstone/verify/drive.mjs prove --steps-file steps.json --json
//   node whetstone/verify/drive.mjs step "open /" "expect text=Dashboard" --json
//   node whetstone/verify/drive.mjs launch --dry-run
//   node whetstone/verify/drive.mjs cleanup

import { spawn } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { delimiter, dirname, isAbsolute, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "../..");
const CONFIG_PATH = join(HERE, "driver.json");
const argv = process.argv.slice(2);
const wantsJson = argv.includes("--json");
const dryRun = argv.includes("--dry-run");
const args = argv.filter((value) => value !== "--json" && value !== "--dry-run");
const command = args[0] ?? "help";

const HELP = `Verification driver for this repository.

Commands (all accept --json; destructive ones accept --dry-run):
  doctor                     Is this instance worth driving? Read-only.
  launch                     Start the app as configured and wait until ready.
  prove --steps-file <file>  Launch, run the steps in one session, capture
                             evidence after every step, clean up, print a verdict.
  step <step> [<step> ...]   Run ad-hoc steps the same way (exploration).
  cleanup                    Stop anything this driver started. Evidence stays.
  help                       This text.

Steps (web surface):
  open <path|url>            Navigate, relative to the launched base URL.
  click <selector>           Click a CSS selector, or text=<visible text>.
  type <selector> <text>     Focus and type.
  press <key>                Enter, Escape, Tab, ArrowRight, ...
  wait <selector>            Wait for a selector or text=<text> (10s).
  expect <selector>          Assert it is present and visible (text=<text> works).
  expect-not <selector>      Assert it is absent or hidden.
  expect-count <selector> <n>
  viewport <width> <height>
  screenshot <name>
  eval <js>                  Assert a JavaScript expression is truthy.
Steps (cli surface):  run <argv...> · expect-output <text> · expect-exit <code>
Steps (http surface): request <METHOD> <path> [json] · expect-status <code> · expect-body <text>

Configure the app in driver.json: surface (web | cli | http), launch
(argv, ready pattern with one URL capture group, timeout), and base_url.`;

function emit(value, code = 0) {
  if (wantsJson) {
    console.log(JSON.stringify(value));
  } else if (typeof value === "string") {
    console.log(value);
  } else {
    console.log(JSON.stringify(value, null, 2));
  }
  process.exit(code);
}

function fail(message, detail = {}) {
  emit({ ok: false, state: "unknown", detail: message, ...detail }, 2);
}

function loadConfig() {
  if (!existsSync(CONFIG_PATH)) {
    return { error: `No driver.json beside the driver (${CONFIG_PATH}).` };
  }
  try {
    const config = JSON.parse(readFileSync(CONFIG_PATH, "utf8"));
    if (!["web", "cli", "http"].includes(config.surface)) {
      return { error: "driver.json surface must be web, cli or http." };
    }
    return { config };
  } catch (error) {
    return { error: `driver.json is not valid JSON: ${error.message}` };
  }
}

function which(program) {
  if (program.includes("/")) {
    const path = isAbsolute(program) ? program : join(ROOT, program);
    return existsSync(path) ? path : null;
  }
  for (const directory of (process.env.PATH ?? "").split(delimiter)) {
    const candidate = join(directory, program);
    try {
      if (statSync(candidate).isFile()) return candidate;
    } catch {}
  }
  return null;
}

function chromePath(config) {
  return [
    process.env.CHROME_BIN,
    config.chrome,
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    "/usr/bin/google-chrome",
    "/usr/bin/google-chrome-stable",
    "/usr/bin/chromium",
    "/usr/bin/chromium-browser",
  ].filter(Boolean).find((path) => existsSync(path));
}

function evidenceDir() {
  const directory = process.env.WH_EVIDENCE_DIR || mkdtempSync(join(tmpdir(), "wh-evidence-"));
  mkdirSync(directory, { recursive: true });
  return directory;
}

// State lives beside the evidence so parallel checkouts never share it.
function statePath() {
  const base = process.env.WH_EVIDENCE_DIR ? dirname(process.env.WH_EVIDENCE_DIR) : tmpdir();
  const key = Buffer.from(ROOT).toString("base64url").slice(-24);
  return join(base, `.driver-${key}.json`);
}

const delay = (ms) => new Promise((resolveDelay) => setTimeout(resolveDelay, ms));

// ---------- launch and cleanup ----------

async function launch(config) {
  const spec = config.launch;
  if (!spec?.command?.length) {
    if (config.base_url) return { url: config.base_url, pid: null, external: true };
    throw new Error("driver.json has no launch.command and no base_url.");
  }
  const program = which(spec.command[0]);
  if (!program) throw new Error(`launch program ${spec.command[0]} is not on PATH or in the repository.`);
  const env = { ...process.env, ...(spec.env ?? {}) };
  let bootstrapFile = null;
  const argvList = spec.command.slice(1).map((part) => {
    if (part === "{bootstrap_file}") {
      bootstrapFile = join(evidenceDir(), `.bootstrap-${process.pid}`);
      return bootstrapFile;
    }
    return part.replaceAll("{root}", ROOT);
  });
  const child = spawn(program, argvList, {
    cwd: spec.cwd ? join(ROOT, spec.cwd) : ROOT,
    env,
    detached: true,
    stdio: ["ignore", "pipe", "pipe"],
  });
  const pattern = new RegExp(spec.ready ?? "(https?://[^\\s]+)");
  const timeout = (spec.timeout_seconds ?? 120) * 1000;
  let transcript = "";
  const url = await new Promise((resolveUrl, rejectUrl) => {
    const timer = setTimeout(() => rejectUrl(new Error(`not ready after ${timeout / 1000}s:\n${transcript.slice(-2000)}`)), timeout);
    const onData = (chunk) => {
      transcript += chunk.toString();
      const match = transcript.match(pattern);
      if (match) {
        clearTimeout(timer);
        resolveUrl(match[1] ?? match[0]);
      }
    };
    child.stdout.on("data", onData);
    child.stderr.on("data", onData);
    child.on("exit", (code) => {
      clearTimeout(timer);
      rejectUrl(new Error(`launch exited with ${code} before ready:\n${transcript.slice(-2000)}`));
    });
  });
  child.stdout.removeAllListeners("data");
  child.stderr.removeAllListeners("data");
  child.stdout.resume();
  child.stderr.resume();
  child.unref();
  let entryUrl = url;
  if (bootstrapFile) {
    for (let attempt = 0; attempt < 100 && !existsSync(bootstrapFile); attempt += 1) await delay(50);
    if (existsSync(bootstrapFile)) {
      entryUrl = readFileSync(bootstrapFile, "utf8").trim();
      rmSync(bootstrapFile, { force: true });
    }
  }
  const state = { pid: child.pid, url, started_at: new Date().toISOString() };
  writeFileSync(statePath(), JSON.stringify(state));
  return { url, entryUrl, pid: child.pid, external: false };
}

function cleanup() {
  const path = statePath();
  if (!existsSync(path)) return { stopped: [], detail: "nothing this driver started is running" };
  const state = JSON.parse(readFileSync(path, "utf8"));
  const stopped = [];
  if (state.pid) {
    try {
      process.kill(-state.pid, "SIGTERM");
      stopped.push(state.pid);
    } catch {}
  }
  rmSync(path, { force: true });
  return { stopped, detail: stopped.length ? "stopped the launched app" : "the launched app had already exited" };
}

// ---------- Chrome DevTools Protocol ----------

class Cdp {
  constructor(url) {
    this.socket = new WebSocket(url);
    this.sequence = 0;
    this.pending = new Map();
    this.errors = [];
  }
  open() {
    return new Promise((resolveOpen, rejectOpen) => {
      this.socket.addEventListener("open", resolveOpen, { once: true });
      this.socket.addEventListener("error", rejectOpen, { once: true });
      this.socket.addEventListener("message", ({ data }) => {
        const message = JSON.parse(data);
        if (message.id && this.pending.has(message.id)) {
          const entry = this.pending.get(message.id);
          this.pending.delete(message.id);
          if (message.error) entry.reject(new Error(message.error.message));
          else entry.resolve(message.result);
        } else if (message.method === "Runtime.exceptionThrown") {
          this.errors.push(message.params.exceptionDetails?.exception?.description ?? "page exception");
        }
      });
    });
  }
  send(method, params = {}) {
    const id = ++this.sequence;
    return new Promise((resolveSend, rejectSend) => {
      this.pending.set(id, { resolve: resolveSend, reject: rejectSend });
      this.socket.send(JSON.stringify({ id, method, params }));
    });
  }
  async evaluate(expression) {
    const result = await this.send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description ?? result.exceptionDetails.text);
    return result.result.value;
  }
}

async function browser(config) {
  const chrome = chromePath(config);
  if (!chrome) throw new Error("Chrome or Chromium is not installed (set CHROME_BIN).");
  const profile = mkdtempSync(join(tmpdir(), "wh-driver-profile-"));
  const child = spawn(chrome, [
    "--headless=new", "--remote-debugging-port=0", `--user-data-dir=${profile}`,
    "--no-first-run", "--no-default-browser-check", "--disable-gpu", "--hide-scrollbars",
    "--disable-background-networking", "about:blank",
  ], { stdio: ["ignore", "ignore", "pipe"] });
  const portFile = join(profile, "DevToolsActivePort");
  for (let attempt = 0; attempt < 400 && !existsSync(portFile); attempt += 1) await delay(25);
  if (!existsSync(portFile)) throw new Error("Chrome did not expose a debugging port.");
  const port = readFileSync(portFile, "utf8").split("\n")[0];
  let page;
  for (let attempt = 0; attempt < 400 && !page; attempt += 1) {
    try {
      const targets = await fetch(`http://127.0.0.1:${port}/json/list`).then((response) => response.json());
      page = targets.find((target) => target.type === "page" && !target.url.startsWith("chrome-extension:"));
    } catch {}
    if (!page) await delay(25);
  }
  if (!page) throw new Error("Chrome did not expose a page target.");
  const cdp = new Cdp(page.webSocketDebuggerUrl);
  await cdp.open();
  await cdp.send("Page.enable");
  await cdp.send("Runtime.enable");
  const viewport = config.viewport ?? [1280, 900];
  await cdp.send("Emulation.setDeviceMetricsOverride", { width: viewport[0], height: viewport[1], deviceScaleFactor: 1, mobile: false });
  return {
    cdp,
    close() {
      child.kill("SIGKILL");
      rmSync(profile, { recursive: true, force: true });
    },
  };
}

function selectorExpression(selector) {
  if (selector.startsWith("text=")) {
    const text = JSON.stringify(selector.slice(5));
    return `(() => { const want = ${text}; const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT); let best = null; while (walker.nextNode()) { const node = walker.currentNode; if (node.offsetParent === null && getComputedStyle(node).position !== "fixed") continue; if ((node.innerText || "").trim().includes(want)) best = node; } return best; })()`;
  }
  return `document.querySelector(${JSON.stringify(selector)})`;
}

const visible = (expression) => `(() => { const node = ${expression}; if (!node) return false; const box = node.getBoundingClientRect(); const style = getComputedStyle(node); return box.width > 0 && box.height > 0 && style.visibility !== "hidden" && style.display !== "none" && !node.closest("[hidden]"); })()`;

async function waitFor(cdp, expression, timeout = 10_000) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    if (await cdp.evaluate(expression)) return true;
    await delay(50);
  }
  return false;
}

async function screenshot(cdp, directory, name) {
  const { contentSize } = await cdp.send("Page.getLayoutMetrics");
  const shot = await cdp.send("Page.captureScreenshot", {
    format: "png",
    captureBeyondViewport: true,
    clip: { x: 0, y: 0, width: Math.max(1, Math.ceil(contentSize.width)), height: Math.min(Math.ceil(contentSize.height), 8000), scale: 1 },
  });
  const file = join(directory, `${name.replace(/[^a-z0-9._-]+/gi, "-")}.png`);
  writeFileSync(file, Buffer.from(shot.data, "base64"));
  return file;
}

function splitStep(step) {
  const space = step.indexOf(" ");
  return space === -1 ? [step, ""] : [step.slice(0, space), step.slice(space + 1).trim()];
}

async function webStep(session, base, step, directory, index) {
  const { cdp } = session;
  const [verb, rest] = splitStep(step);
  switch (verb) {
    case "open": {
      const target = /^https?:/.test(rest) ? rest : new URL(rest || "/", base).href;
      await cdp.send("Page.navigate", { url: target });
      await waitFor(cdp, "document.readyState === 'complete'", 15_000);
      await delay(300);
      return `opened ${target.replace(/#.*$/, "")}`;
    }
    case "click": {
      const expression = selectorExpression(rest);
      if (!(await waitFor(cdp, visible(expression)))) throw new Error(`${rest} is not visible`);
      await cdp.evaluate(`(${expression}).click()`);
      await delay(250);
      return `clicked ${rest}`;
    }
    case "type": {
      const [selector, ...words] = rest.split(" ");
      const expression = selectorExpression(selector);
      if (!(await waitFor(cdp, visible(expression)))) throw new Error(`${selector} is not visible`);
      await cdp.evaluate(`(() => { const node = ${expression}; node.focus(); node.value = ${JSON.stringify(words.join(" "))}; node.dispatchEvent(new Event("input", { bubbles: true })); node.dispatchEvent(new Event("change", { bubbles: true })); return true; })()`);
      return `typed into ${selector}`;
    }
    case "press": {
      for (const type of ["keyDown", "keyUp"]) {
        await cdp.send("Input.dispatchKeyEvent", { type, key: rest, code: rest, windowsVirtualKeyCode: { Enter: 13, Escape: 27, Tab: 9, ArrowRight: 39, ArrowLeft: 37, ArrowDown: 40, ArrowUp: 38 }[rest] ?? 0 });
      }
      await delay(150);
      return `pressed ${rest}`;
    }
    case "wait":
      if (!(await waitFor(cdp, visible(selectorExpression(rest))))) throw new Error(`${rest} did not appear`);
      return `saw ${rest}`;
    case "expect":
      if (!(await waitFor(cdp, visible(selectorExpression(rest)), 5_000))) throw new Error(`expected ${rest} to be visible`);
      return `verified ${rest}`;
    case "expect-not":
      if (await cdp.evaluate(visible(selectorExpression(rest)))) throw new Error(`expected ${rest} to be absent`);
      return `verified absence of ${rest}`;
    case "expect-count": {
      const cut = rest.lastIndexOf(" ");
      const selector = rest.slice(0, cut);
      const want = Number(rest.slice(cut + 1));
      const count = await cdp.evaluate(`document.querySelectorAll(${JSON.stringify(selector)}).length`);
      if (count !== want) throw new Error(`expected ${want} × ${selector}, found ${count}`);
      return `counted ${count} × ${selector}`;
    }
    case "viewport": {
      const [width, height] = rest.split(" ").map(Number);
      await cdp.send("Emulation.setDeviceMetricsOverride", { width, height, deviceScaleFactor: 1, mobile: width < 768 });
      await delay(200);
      return `viewport ${width}×${height}`;
    }
    case "screenshot":
      await screenshot(cdp, directory, `${String(index).padStart(2, "0")}-${rest || "shot"}`);
      return `captured ${rest}`;
    case "eval":
      if (!(await cdp.evaluate(rest))) throw new Error(`expression was falsy: ${rest}`);
      return "expression held";
    default:
      throw new Error(`unknown web step "${verb}"; run help for the step list`);
  }
}

async function cliStep(context, step) {
  const [verb, rest] = splitStep(step);
  if (verb === "run") {
    const parts = rest.match(/"[^"]*"|'[^']*'|\S+/g)?.map((part) => part.replace(/^["']|["']$/g, "")) ?? [];
    const program = which(parts[0] ?? "");
    if (!program) throw new Error(`${parts[0]} is not on PATH or in the repository`);
    const result = await new Promise((resolveRun) => {
      const child = spawn(program, parts.slice(1), { cwd: ROOT, stdio: ["ignore", "pipe", "pipe"] });
      let output = "";
      child.stdout.on("data", (chunk) => { output += chunk; });
      child.stderr.on("data", (chunk) => { output += chunk; });
      child.on("exit", (code) => resolveRun({ code, output }));
    });
    context.last = result;
    return `ran ${parts[0]} (exit ${result.code})`;
  }
  if (verb === "expect-output") {
    if (!context.last?.output.includes(rest)) throw new Error(`output did not contain ${rest}`);
    return `output contained ${rest}`;
  }
  if (verb === "expect-exit") {
    if (String(context.last?.code) !== rest) throw new Error(`exit was ${context.last?.code}, expected ${rest}`);
    return `exit ${rest}`;
  }
  throw new Error(`unknown cli step "${verb}"`);
}

async function httpStep(context, base, step) {
  const [verb, rest] = splitStep(step);
  if (verb === "request") {
    const [method, path, ...body] = rest.split(" ");
    const response = await fetch(new URL(path, base), {
      method,
      headers: body.length ? { "content-type": "application/json" } : {},
      body: body.length ? body.join(" ") : undefined,
    });
    context.last = { status: response.status, body: await response.text() };
    return `${method} ${path} → ${response.status}`;
  }
  if (verb === "expect-status") {
    if (String(context.last?.status) !== rest) throw new Error(`status was ${context.last?.status}, expected ${rest}`);
    return `status ${rest}`;
  }
  if (verb === "expect-body") {
    if (!context.last?.body.includes(rest)) throw new Error(`body did not contain ${rest}`);
    return `body contained ${rest}`;
  }
  throw new Error(`unknown http step "${verb}"`);
}

async function runSteps(config, steps) {
  const directory = evidenceDir();
  const results = [];
  const failures = [];
  let app = null;
  let session = null;
  const context = {};
  try {
    if (config.surface !== "cli") app = await launch(config);
    if (config.surface === "web") {
      session = await browser(config);
      await session.cdp.send("Page.navigate", { url: app.entryUrl ?? app.url });
      await waitFor(session.cdp, "document.readyState === 'complete'", 15_000);
      await delay(400);
    }
    for (const [index, step] of steps.entries()) {
      const started = Date.now();
      try {
        const detail = config.surface === "web"
          ? await webStep(session, app.url, step, directory, index + 1)
          : config.surface === "http"
            ? await httpStep(context, app.url, step)
            : await cliStep(context, step);
        results.push({ step, ok: true, detail, ms: Date.now() - started });
      } catch (error) {
        results.push({ step, ok: false, detail: error.message, ms: Date.now() - started });
        failures.push({ location: `step ${index + 1}: ${step}`, message: error.message });
        break;
      }
    }
    if (session) {
      await screenshot(session.cdp, directory, "final");
      if (session.cdp.errors.length) {
        failures.push({ location: "page", message: `page errors: ${session.cdp.errors.slice(0, 3).join(" | ")}` });
      }
    } else {
      writeFileSync(join(directory, "transcript.json"), JSON.stringify({ steps: results, last: context.last ?? null }, null, 2));
    }
  } finally {
    session?.close();
    if (app && !app.external) cleanup();
  }
  return {
    state: failures.length ? "fail" : "pass",
    steps: results,
    failures,
    evidence_dir: directory,
  };
}

// ---------- commands ----------

async function doctor() {
  const { config, error } = loadConfig();
  if (error) return emit({ ok: false, detail: error }, 1);
  const problems = [];
  const [major] = process.versions.node.split(".").map(Number);
  if (major < 22) problems.push(`Node ${process.versions.node} is too old; Node 22+ provides WebSocket and fetch.`);
  if (config.launch?.command?.length && !which(config.launch.command[0])) {
    problems.push(`launch program ${config.launch.command[0]} is not on PATH or in the repository.`);
  }
  if (!config.launch?.command?.length && !config.base_url && config.surface !== "cli") {
    problems.push("driver.json needs launch.command or base_url.");
  }
  if (config.surface === "web" && !chromePath(config)) problems.push("Chrome or Chromium is not installed (set CHROME_BIN).");
  for (const artifact of config.fresh ?? []) {
    const built = join(ROOT, artifact.artifact);
    if (!existsSync(built)) {
      problems.push(`STALE BUILD: ${artifact.artifact} does not exist; build before driving.`);
      continue;
    }
    const builtAt = statSync(built).mtimeMs;
    const newer = (artifact.sources ?? []).find((source) => {
      const path = join(ROOT, source);
      return existsSync(path) && newestMtime(path) > builtAt;
    });
    if (newer) problems.push(`STALE BUILD: ${newer} changed after ${artifact.artifact} was built; rebuild before driving.`);
  }
  emit({
    ok: problems.length === 0,
    detail: problems.length ? problems.join(" ") : `${config.surface} surface ready to drive`,
    surface: config.surface,
    root: ROOT,
  }, problems.length ? 1 : 0);
}

function newestMtime(path) {
  const stat = statSync(path);
  if (!stat.isDirectory()) return stat.mtimeMs;
  let newest = stat.mtimeMs;
  const stack = [path];
  while (stack.length) {
    const current = stack.pop();
    let entries = [];
    try {
      entries = readdirSyncSafe(current);
    } catch {}
    for (const entry of entries) {
      if (entry.name === "node_modules" || entry.name === "target" || entry.name.startsWith(".")) continue;
      const full = join(current, entry.name);
      if (entry.isDirectory()) stack.push(full);
      else newest = Math.max(newest, statSync(full).mtimeMs);
    }
  }
  return newest;
}

function readdirSyncSafe(path) {
  return readdirSync(path, { withFileTypes: true });
}

async function main() {
  switch (command) {
    case "help":
    case "--help":
      return emit(wantsJson ? { ok: true, help: HELP } : HELP);
    case "doctor":
      return doctor();
    case "launch": {
      const { config, error } = loadConfig();
      if (error) return fail(error);
      if (dryRun) return emit({ ok: true, dry_run: true, would_run: config.launch?.command ?? null, base_url: config.base_url ?? null });
      try {
        const app = await launch(config);
        return emit({ ok: true, url: app.url, pid: app.pid, stop_with: "node whetstone/verify/drive.mjs cleanup" });
      } catch (launchError) {
        return fail(launchError.message);
      }
    }
    case "cleanup":
      if (dryRun) return emit({ ok: true, dry_run: true, state_file: statePath(), exists: existsSync(statePath()) });
      return emit({ ok: true, ...cleanup() });
    case "prove":
    case "step": {
      const { config, error } = loadConfig();
      if (error) return fail(error);
      let steps = args.slice(1);
      if (command === "prove") {
        const at = args.indexOf("--steps-file");
        if (at === -1 || !args[at + 1]) return fail("prove needs --steps-file <file>.");
        try {
          steps = JSON.parse(readFileSync(args[at + 1], "utf8")).steps ?? [];
        } catch (readError) {
          return fail(`steps file unreadable: ${readError.message}`);
        }
      }
      if (!steps.length) return fail("no steps to run.");
      if (dryRun) return emit({ ok: true, dry_run: true, steps });
      try {
        const verdict = await runSteps(config, steps);
        return emit({ ok: verdict.state === "pass", ...verdict }, verdict.state === "pass" ? 0 : 1);
      } catch (runError) {
        cleanup();
        return fail(runError.message);
      }
    }
    default:
      return fail(`unknown command "${command}"; run help.`);
  }
}

main();
